/* @socom-skeleton body LoadFromRdr__14CGameDlgDesignFP5_zrdr */
void CGameDlgDesign::LoadFromRdr(_zrdr* reader)
{
	/* 0x398f50 */
	m_libs.clear();
	m_font = "";
	m_background = "";
	m_useMpeg = false;
	m_script = "";
	m_animations.clear();
	m_controls.clear();
	m_objects.clear();
	m_models.clear();

	if (char* lib = zrdr_findstring(reader, "LIBRARY"))
	{
		m_libs.resize(m_libs.size() + 1);
		m_libs.back() = lib;
	}

	_zrdr* libs = zrdr_findtag(reader, "LIBRARIES");
	u32 count = (libs != NULL && libs->IsArray()) ? libs->array->integer - 1 : 0;

	for (u32 i = 0; i < count; i++)
	{
		_zrdr* item = libs->Get(i);
		char* name = item->type == ZRDR_STRING ? item->string : NULL;
		m_libs.resize(m_libs.size() + 1);
		m_libs.back() = name;
	}

	m_font = zrdr_findstring(reader, "FONT");
	m_fontlib = zrdr_findtag(reader, "NOFONTLIB") == NULL;

	if (_zrdr* background = zrdr_findtag(reader, "BACKGROUND"))
	{
		if (char* type = zrdr_findstring(background, "TYPE"))
		{
			if (strcasecmp(type, "IMAGE") == 0)
				m_useMpeg = false;
			else if (strcasecmp(type, "MPEG") == 0)
				m_useMpeg = true;
		}

		m_background = zrdr_findstring(background, "FILENAME");
	}

	_zrdr* anims = zrdr_findtag(reader, "ANIMATIONS");
	count = (anims != NULL && anims->IsArray()) ? anims->array->integer - 1 : 0;

	for (u32 i = 0; i < count; i++)
	{
		m_animations.resize(m_animations.size() + 1);
		ParseButtonAnim(anims->Get(i), &m_animations.back());
	}

	LoadDlgObjects(&m_controls, reader, "CONTROLS", GetControlSpec);
	LoadDlgObjects(&m_objects, reader, "OBJECTS", GetObjectSpec);
	m_script = zrdr_findstring(reader, "SCRIPT_LIBRARY");
	LoadModels(reader);
}

/* @socom-skeleton stub LoadModels__14CGameDlgDesignFP5_zrdr */
void CGameDlgDesign::LoadModels(_zrdr *reader)
{
	/* 0x398c90: one CDlgDesignModel per MODELS entry: NAME, MODEL, AZIMUTH, ELEV,
	 * DISTANCE (default 20), the rotations and USEMODELUIVAR. ELF quirk: ROTX, ROTY and
	 * ROTZ are all stored to the first rotation, so it ends up ROTZ (0 when absent). */
	_zrdr* models = zrdr_findtag(reader, "MODELS");

	for (u32 i = 0; (s32)i < (s32)(models != NULL && models->IsArray() ? models->array->integer - 1 : 0); i++)
	{
		m_models.resize(m_models.size() + 1);
		CDlgDesignModel& model = m_models[m_models.size() - 1];
		_zrdr* entry = models->Get(i);

		char* name = zrdr_findstring(entry, "NAME");

		if (name != NULL)
			model.m_name.assign(name, strlen(name));
		else
			model.m_name.clear();

		char* file = zrdr_findstring(entry, "MODEL");

		if (file != NULL)
			model.m_model.assign(file, strlen(file));
		else
			model.m_model.clear();

		f32 value = 0.0f;
		zrdr_findreal(entry, "AZIMUTH", &value, 1);
		model.m_azimuth = value;
		value = 0.0f;
		zrdr_findreal(entry, "ELEV", &value, 1);
		model.m_elevation = value;
		value = 20.0f;
		zrdr_findreal(entry, "DISTANCE", &value, 1);
		model.m_distance = value;
		value = 0.0f;
		zrdr_findreal(entry, "ROTX", &value, 1);
		model.m_rotation[0] = value;
		value = 0.0f;
		zrdr_findreal(entry, "ROTY", &value, 1);
		model.m_rotation[0] = value;
		value = 0.0f;
		zrdr_findreal(entry, "ROTZ", &value, 1);
		model.m_rotation[0] = value;

		if (zrdr_findtag(entry, "USEMODELUIVAR") != NULL)
			model.m_usemodeluivar = true;
	}
}

